        if(task.status === 'needs_attention') card.append(node('p',task.desktopAttention || '\u5B58\u5728\u5F85\u5904\u7406\u6743\u9650\u8BF7\u6C42\u3002\u8BF7\u5728\u804A\u5929\u4E2D\u68C0\u67E5\u5177\u4F53\u64CD\u4F5C\u5E76\u5904\u7406\uFF1B\u672C\u5361\u7247\u4E0D\u4F1A\u81EA\u52A8\u6279\u51C6\u3002','notice'));
        for(const field of ['error','cleanupError','persistenceError']) if(task[field]) card.append(node('p',task[field],'notice'));
